const list = (s) => String(s ?? '').split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
const c = $('Configuration').first().json;
const words = list(c.titleKeywords);
const today = $now.toFormat('yyyy-MM-dd');

const rows = [];
for (const { json: r } of $input.all()) {
  const title = String(r.title ?? '').toLowerCase();
  if (!r.url) continue;
  if (words.length && !words.some((w) => title.includes(w))) continue;
  rows.push({
    json: {
      url: r.url,
      company: r.company_name ?? r.company_slug ?? '',
      title: r.title ?? '',
      department: r.department ?? '',
      location: r.location ?? '',
      remote: r.remote ?? '',
      ats: r.source ?? '',
      published: r.published_at ?? '',
      first_seen: today,
    },
  });
}
return rows;

// A job counts as new when its URL is not in the sheet yet.
const known = new Set($input.all().map((i) => String(i.json.url ?? '')).filter(Boolean));
const fresh = [];
for (const item of $('Keep relevant roles').all()) {
  if (known.has(item.json.url)) continue;
  known.add(item.json.url);
  fresh.push({ json: item.json });
}
return fresh;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $('Configuration').first().json;
const min = Number(c.spikeThreshold);
const rows = $('Find jobs not seen before').all().map((i) => i.json);
const firstRun = !$('Read known jobs from sheet').all().some((i) => i.json.url);

const byCompany = {};
for (const r of rows) (byCompany[r.company] ??= []).push(r);
const ranked = Object.entries(byCompany).sort((a, b) => b[1].length - a[1].length);

if (firstRun) {
  return [{ json: {
    subject: `Hiring tracker baseline saved: ${rows.length} open jobs`,
    html: `<p>First run: ${rows.length} open jobs from ${ranked.length} companies are now stored as the baseline. ` +
      'From the next run on you only get jobs that are new.</p>',
  } }];
}

const spikes = ranked.filter(([, jobs]) => jobs.length >= min);
const part = ([name, jobs]) => `<h3>${esc(name)}: ${jobs.length} new</h3><ul>` +
  jobs.map((j) => `<li><a href="${esc(j.url)}">${esc(j.title)}</a> ${esc(j.location)}</li>`).join('') + '</ul>';
const others = ranked.filter(([, jobs]) => jobs.length < min);
const html = (spikes.length ? `<h2>Hiring spikes (${min} or more new jobs)</h2>${spikes.map(part).join('')}` : '') +
  (others.length ? `<h2>Other new jobs</h2>${others.map(part).join('')}` : '');
return [{ json: {
  subject: `New jobs: ${rows.length}, hiring spikes: ${spikes.length}`,
  html,
} }];
